export const BODY: string = "\n<p>تصویریں زیادہ تر ویب سائٹس کا سب سے بھاری حصہ ہیں۔ آہستہ لوڈ ہونے والے صفحے میں عام طور پر تصویروں کا قصور ہوتا ہے، اور انہیں درست کرنا تیز ترین رفتار فائدہ ہے۔</p>\n<p>یہ رہنما پورا اصلاح عمل بتاتا ہے۔ آپ صفحہ کا آڈٹ کریں گے، درست پری سیٹ چنیں گے، تصویروں کو بہتر کریں گے اور HTML کو جگہ پر چسپاں کریں گے۔</p>\n<p>یہ بلاگ، دکانوں اور کاروباری سائٹس کے لیے کام کرتا ہے، اور آپ کو کاپی اور چسپاں کرنے سے زیادہ کوڈنگ تجربہ نہیں چاہیے۔</p>\n<h2 id=\"audit-first\">مرحلہ 1: پہلے صفحے کا آڈٹ کریں</h2>\n<p>کچھ بھی بہتر کرنے سے پہلے معلوم کریں کہ کون سی تصویریں مسئلہ ہیں۔ صفحہ کھولیں اور نوٹ کریں کہ کون سی تصویریں دکھائی دینے میں سست لگتی ہیں۔</p>\n<p>صفحہ ناپنے کے لیے مفت رفتار ٹول استعمال کریں۔ یہ سب سے بھاری تصویریں درج کرتا ہے اور دکھاتا ہے کہ ہر ایک لوڈ وقت میں کتنا خرچ کرتی ہے۔</p>\n<p>صفحے کا کل تصویر وزن نوٹ کریں۔ 5 MB تصویروں والا صفحہ واضح مسئلہ رکھتا ہے، جبکہ 500 KB والا صفحہ پہلے سے اچھی حالت میں ہے۔</p>\n<h2 id=\"step-2-open\">مرحلہ 2: ویب تصویر اصلاح ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/website-ke-liye-tasveer-optimize-karein/\">Web Image Optimizer</a> کھولیں۔ کوئی اکاؤنٹ یا انسٹال نہیں چاہیے۔</p>\n<p>ٹول مکمل طور پر آپ کے آلے پر چلتا ہے۔ آپ کی تصویریں مقامی طور پر پروسیس ہوتی ہیں اور کبھی سرور پر اپ لوڈ نہیں ہوتیں۔</p>\n<p>اگر آپ پوری سائٹ بہتر کر رہے ہیں تو بیچوں میں کام کریں۔ زیادہ تر براؤزر کے لیے ایک وقت میں تیس تصویریں آرام دہ بیچ سائز ہے۔</p>\n<h2 id=\"step-3-preset\">مرحلہ 3: درست پری سیٹ چنیں</h2>\n<p>وہ پری سیٹ چنیں جو اس جگہ سے میل کھائے جہاں تصویر دکھائی دے گی۔ ہیرو تصویر، مصنوعات شاٹ اور تھمب نیل ہر ایک کا اپنا پری سیٹ ہے۔</p>\n<p>ای کامرس مصنوعات پری سیٹ پہلے سے طے شدہ ہے۔ یہ تصویروں کو 82 فیصد کوالٹی پر WebP میں 1200 پکسل چوڑا محدود کرتا ہے، جو زیادہ تر مصنوعات تصویروں کو سوٹ کرتا ہے۔</p>\n<p>بلاگ نمایاں تصویر کے لیے لے آؤٹ کے حساب سے ہیرو یا کارڈ پری سیٹ استعمال کریں۔ پری سیٹ کو دکھائی دینے والے سائز سے ملائیں، فائل سائز سے نہیں۔</p>\n<h2 id=\"step-4-upload\">مرحلہ 4: تصویریں اپ لوڈ کریں</h2>\n<p>تصویریں اپ لوڈ والے حصے پر گھسیٹ دیں یا براؤز کرنے کے لیے ٹیپ کریں۔ JPG، PNG، WebP اور HEIC فائلیں قبول ہوتی ہیں۔</p>\n<p>اپنے پاس اعلیٰ ترین کوالٹی والے اصل اپ لوڈ کریں۔ 12 میگا پکسل اصل اصلاح کرنے والے کو چھوٹی کاپی سے کہیں زیادہ کام دیتا ہے۔</p>\n<p>بیچ کے لیے ایک صفحے کی تمام تصویریں ایک ساتھ شامل کریں۔ وہ پری سیٹ شیئر کرتی ہیں، جس سے نتائج مستقل رہتے ہیں۔</p>\n<h2 id=\"step-5-customise\">مرحلہ 5: ترتیبات اپنی مرضی سے طے کریں</h2>\n<p>پری سیٹ چننے کے بعد ترتیبات ایڈجسٹ کریں اگر سلاٹ اس کا تقاضا کرے۔ ڈیزائن کے مطابق ابعاد، فارمیٹ یا کوالٹی بدلیں۔</p>\n<p>ابعاد کو دکھائی دینے والے سائز کے قریب رکھیں۔ 800 پکسل چوڑا دکھایا جانے والا تصویر فائل میں 2400 پکسل نہیں ہونی چاہیے۔</p>\n<p>جب بیچ میں بڑی اور چھوٹی تصویریں ملی ہوں تو Only downscale آن کریں۔ یہ آئیکن اور تھمب نیل کو بڑا کھینچنے سے بچاتا ہے۔</p>\n<h2 id=\"step-6-preview\">مرحلہ 6: نتائج کا پیش نظارہ دیکھیں</h2>\n<p>ڈاؤن لوڈ سے پہلے ہر بہتر شدہ تصویر کو مکمل سائز پر پیش نظارہ دیکھیں۔ چھوٹا تھمب نیل وہ مسائل چھپاتا ہے جو مکمل سائز پر واضح ہیں۔</p>\n<p>پہلے باریک تفصیل جانچیں۔ کپڑے کی بناوٹ، متن اور کنارے کمپریشن کے تحت نرم ہونے والی پہلی چیزیں ہیں۔</p>\n<p>چند نتائج کا اپنے اصل سے موازنہ کریں۔ چھوٹے فرق عام ہیں؛ ناقابل پڑھ متن یا دھبے والی جلد نہیں۔</p>\n<h2 id=\"step-7-copy-html\">مرحلہ 7: HTML ٹیگ کاپی کریں</h2>\n<p>ہر تصویر کے لیے Copy Image Tag پر کلک کریں۔ ٹیگ میں ماخذ، ابعاد، alt متن اور لوڈ رویہ شامل ہیں، چسپاں کرنے کے لیے تیار۔</p>\n<p>ٹیگ میں alt متن جانچیں۔ اگر بنایا گیا متن تصویر کو اچھی طرح بیان نہ کرے تو اسے ترمیم کریں۔</p>\n<p>تصدیق کریں کہ لوڈنگ وصف درست ہے۔ ہیرو فوراً لوڈ ہونے چاہییں، جبکہ فولڈ سے نیچے کی تصویریں سست لوڈ ہونی چاہییں۔</p>\n<h2 id=\"step-8-upload\">مرحلہ 8: اپ لوڈ کریں اور صفحے کو آزمائیں</h2>\n<p>بہتر شدہ تصویریں اپنی سائٹ پر اپ لوڈ کریں۔ ٹول نے جو فائل نام بنائے، وہی استعمال کریں، تاکہ HTML ٹیگ فائلوں سے میل کھائیں۔</p>\n<p>صفحہ تازہ براؤزر ٹیب میں کھولیں۔ جانچیں کہ ہر تصویر دکھائی دیتی ہے اور کچھ بھی کھینچا ہوا یا دھندلا نہیں لگتا۔</p>\n<p>رفتار ٹول دوبارہ چلائیں اور اعداد کا موازنہ کریں۔ کل تصویر وزن تیزی سے گرنا چاہیے، اور لوڈ وقت بھی اس کے ساتھ۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر تصویر دھندلی لگے تو ماخذ شاید بہت چھوٹا تھا۔ اسی پری سیٹ کے ساتھ بڑے اصل سے دوبارہ بہتر کریں۔</p>\n<p>اگر صفحہ پھر بھی آہستہ لوڈ ہو تو غیر بہتر تصویریں جانچیں۔ ایک بھولا ہوا 5 MB بینر پورا بیچ برباد کر سکتا ہے۔</p>\n<p>اگر تصویریں کھینچی ہوئی لگیں تو ٹیگ میں ابعاد فائل سے میل نہیں کھاتے۔ ہاتھ سے ترمیم کرنے کی بجائے ٹول سے ٹیگ دوبارہ کاپی کریں۔</p>\n<h2 id=\"blog-workflow\">ورک فلو: بلاگ پوسٹ</h2>\n<p>پوسٹ کی تصویریں جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ تھمب نیل کے لیے کارڈ پری سیٹ اور نمایاں تصویر کے لیے ہیرو پری سیٹ استعمال کریں۔</p>\n<p>نمایاں تصویر کا احتیاط سے پیش نظارہ دیکھیں۔ یہ صفحے کی سب سے بڑی تصویر ہے اور قارئین پہلے اسی کا فیصلہ کرتے ہیں۔</p>\n<p>HTML ٹیگ کاپی کریں اور انہیں پوسٹ میں چسپاں کریں۔ شائع کرنے سے پہلے ہر ایک پر alt متن جانچیں۔</p>\n<h2 id=\"shop-workflow\">ورک فلو: مصنوعات صفحہ</h2>\n<p>مصنوعات کے شاٹ جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ مستقل نتائج کے لیے ای کامرس مصنوعات پری سیٹ استعمال کریں۔</p>\n<p>سب سے تفصیلی مصنوعات کا پہلے پیش نظارہ دیکھیں۔ کپڑے کی بناوٹ اور چھپے لیبل نرم ہونے والی پہلی چیزیں ہیں۔</p>\n<p>HTML ٹیگ کاپی کریں اور انہیں مصنوعات صفحے میں چسپاں کریں۔ ہر تصویر کی جگہ کے لیے لوڈنگ وصف درست ہونے کی تصدیق کریں۔</p>\n<h2 id=\"speed-tools\">مفت رفتار ٹول اچھی طرح استعمال کرنا</h2>\n<p>مفت رفتار ٹول آپ کا صفحہ ناپتے ہیں اور مسائل درج کرتے ہیں۔ وہ کسی بھی اصلاح کام کے لیے بہترین نقطہ آغاز ہیں۔</p>\n<p>ٹول لائیو صفحے پر چلائیں، مقامی کاپی پر نہیں۔ لائیو صفحے میں ہوسٹنگ، CDN اور حقیقی دنیا کی شرائط شامل ہیں جن کا آپ کے زائرین سامنا کرتے ہیں۔</p>\n<p>پہلے تصویر سفارشات پڑھیں۔ وہ بالکل وہ فائلیں نامزد کرتی ہیں جو سب سے زیادہ وقت خرچ کرتی ہیں، جو بتاتا ہے کہ کہاں سے شروع کریں۔</p>\n<h2 id=\"image-sizes-by-slot\">صفحے کی سلاٹ کے حساب سے سائز چننا</h2>\n<p>صفحے کی ہر سلاٹ کا قدرتی تصویر سائز ہوتا ہے۔ فائل کو سلاٹ سے ملانا ویب اصلاح کی بنیادی مہارت ہے۔</p>\n<p>ہیرو تصویروں کو سب سے بڑی فائلیں چاہییں، اکثر 1200 سے 1600 پکسل چوڑی۔ وہ اسکرین بھرتی ہیں، اس لیے انہیں تیز رہنا چاہیے۔</p>\n<p>بلاگ پوسٹ میں نمایاں تصویریں 800 سے 1200 پکسل کو سوٹ کرتی ہیں۔ وہ بڑی ہیں مگر مکمل اسکرین نہیں، اس لیے درمیانہ سائز کام کرتا ہے۔</p>\n<h2 id=\"srcset-basics\">عمل میں جوابی تصویریں</h2>\n<p>جوابی تصویریں مختلف اسکرینوں کو مختلف فائلیں دیتی ہیں۔ فون کو چھوٹی فائل ملتی ہے، جبکہ ڈیسک ٹاپ کو بڑی فائل ملتی ہے۔</p>\n<p>srcset وصف دستیاب سائز درج کرتا ہے، اور براؤزر اس اسکرین کے لیے درست سائز چنتا ہے جس پر وہ چلتا ہے۔</p>\n<p>فی تصویر دو یا تین سائز بنائیں۔ موبائل سائز، ٹیبلٹ سائز اور ڈیسک ٹاپ سائز تقریباً ہر زائر کو پورا کرتے ہیں۔</p>\n<h2 id=\"image-seo\">اصلاح کے دوران تصویر SEO</h2>\n<p>اصلاح اور SEO ایک ساتھ جاتے ہیں۔ اچھی طرح بیان شدہ تصویروں والا تیز صفحہ گمنام فائلوں والے سست صفحے سے بہتر درجہ پاتا ہے۔</p>\n<p>بیانی فائل نام استعمال کریں۔ blue-cotton-shirt.jpg جیسا نام سرچ انجن کو بتاتا ہے کہ تصویر کیا دکھاتی ہے۔</p>\n<p>ہر تصویر کے لیے حقیقی alt متن لکھیں۔ مواد کو ایک جملے میں بیان کریں، اور وہ اہم تفصیل شامل کریں جسے تلاش کرنے والا ڈھونڈے گا۔</p>\n<h2 id=\"maintenance\">وقت کے ساتھ بہتر شدہ تصویریں برقرار رکھنا</h2>\n<p>اصلاح ایک بار کا کام نہیں۔ نئی تصویریں ہر ہفتے آتی ہیں، اور ہر ایک کو پچھلی جیسا ہی سلوک چاہیے۔</p>\n<p>اصلاح کو شائع کرنے کی چیک لسٹ میں شامل کریں۔ ہر پوسٹ لائیو جانے سے پہلے اصلاح ٹول سے گزرنی چاہیے۔</p>\n<p>سائٹ کا سہ ماہی آڈٹ کریں۔ اصلاح عادت سے پہلے کی پرانی تصویریں اکثر اب بھی بھاری ہیں، اور ایک بیچ انہیں تیزی سے درست کرتا ہے۔</p>\n<h2 id=\"team-optimisation\">ٹیموں کے لیے اصلاح معیار</h2>\n<p>جو ٹیمیں ایک ساتھ شائع کرتی ہیں، انہیں مشترکہ معیار چاہیے۔ پہلی پوسٹ سے پہلے پری سیٹ، نام دینے کے انداز اور سائز بجٹ پر متفق ہوں۔</p>\n<p>معیار کو ایک صفحے میں لکھیں۔ ٹیم وکی میں مختصر رہنما سو چھوٹے سوالات روکتا ہے۔</p>\n<p>ہر شائع پر تصویر وزن جانچنے کے لیے ایک شخص مقرر کریں۔ دوسری آنکھیں وہ بھاری تصویر پکڑتی ہیں جو مصنف چھوڑ گیا۔</p>\n<h2 id=\"common-speed-myths\">نظر انداز کرنے والے رفتار افسانے</h2>\n<p>ایک افسانہ کہتا ہے کہ صرف ہوم پیج رفتار کے لیے اہم ہے۔ حقیقت میں زائرین بلاگ پوسٹ اور مصنوعات صفحوں پر آتے ہیں، اور انہیں بھی تیز ہونا چاہیے۔</p>\n<p>دوسرا افسانہ کہتا ہے کہ تیز ہوسٹ سست تصویروں کو درست کرتا ہے۔ ہوسٹنگ مدد کرتی ہے، مگر 5 MB تصویر کسی بھی ہوسٹ پر سست ہے، اور اصلاح ہی واحد حل ہے۔</p>\n<p>تیسرا افسانہ کہتا ہے کہ صرف WebP سب کچھ حل کرتا ہے۔ فارمیٹ مدد کرتا ہے، مگر ابعاد اور سست لوڈنگ فارمیٹ انتخاب جتنی ہی اہم ہیں۔</p>\n<h2 id=\"final-check-speed\">شائع کرنے سے پہلے آخری جانچ</h2>\n<p>تمام تصویریں بہتر ہونے کے بعد رفتار ٹول ایک آخری بار چلائیں۔ تصدیق کریں کہ کل تصویر وزن گرا اور لوڈ وقت بہتر ہوا۔</p>\n<p>صفحہ موبائل کنکشن پر حقیقی فون پر لوڈ کریں۔ لیب آزمائش کے اعداد مفید ہیں، مگر فون پر احساس سچ ہے۔</p>\n<p>ہر تصویر کو ایک بار اور بصری طور پر جانچیں۔ دھندلے ہیرو والا تیز صفحہ کامیابی نہیں، اور احتیاط سے پیش نظارہ اسے پکڑتا ہے۔</p>\n<h2 id=\"keep-learning\">ہر صفحے سے سیکھتے رہیں</h2>\n<p>ہر صفحہ جسے آپ بہتر کرتے ہیں، کچھ سکھاتا ہے۔ نوٹ کریں کون سا پری سیٹ کام آیا، کون سی تصویر سب سے مشکل تھی، اور رفتار اعداد نے کیا کیا، کیونکہ وہ سبق ہر صفحے کے ساتھ جمع ہوتے ہیں جسے آپ درست کرتے ہیں اور ہر سائٹ کے ساتھ جسے آپ بہتر کرتے ہیں۔</p>\n<p>وہ نوٹ آپ کی کھیل کتاب بن جاتے ہیں۔ اگلا صفحہ کم وقت لیتا ہے کیونکہ پچھلے صفحے نے سوالات کے جواب پہلے دے دیے۔</p>\n<p>اصلاح ٹول کا مکمل رہنما جاننے کے لیے <a href=\"/ur/blog/web-tasveer-optimizer-rehnumai/\">Web Image Optimizer: Complete Guide</a> پڑھیں۔ Core Web Vitals کی گہری تفصیل کے لیے <a href=\"/ur/blog/tasveer-optimization-core-web-vitals/\">Image Optimization for Core Web Vitals: LCP and File Size</a> دیکھیں۔ سادہ سائز اہداف کے لیے <a href=\"/ur/tasveer-compress-karein-200kb-tak/\">200KB کمپریسر</a> زیادہ تر ویب تصویروں کو پورا کرتا ہے۔</p>\n";

